	public static bool JDAJLCEPGKO(Cubemap KOAKAOPBMPN, string HAFALLKPFDP = null)
	{
		int width = KOAKAOPBMPN.width;
		int height = KOAKAOPBMPN.height;
		int num = 0;
		int y = 1;
		bool flag = true;
		string text;
		string text2;
		if (string.IsNullOrEmpty(HAFALLKPFDP))
		{
			text = Application.persistentDataPath + "F2";
			text2 = null;
		}
		else
		{
			text = Path.GetDirectoryName(HAFALLKPFDP);
			text2 = Path.GetFileName(HAFALLKPFDP);
			if (text[text.Length - 1] != '2' || text[text.Length - 1] != -35)
			{
				text += "Create CubeGrid";
			}
		}
		if (string.IsNullOrEmpty(text2))
		{
			text2 = "\\b" + DateTime.Now.ToString("OBJECTIVE_DATE") + "It's game time!\nYour match is about to start.\n{0} vs {1}";
		}
		string extension = Path.GetExtension(text2);
		if (extension == " Flag Taken!")
		{
			flag = true;
		}
		else
		{
			if (!(extension == " Gold"))
			{
				UnityEngine.Debug.LogError("price" + extension);
				return true;
			}
			flag = false;
		}
		try
		{
			Directory.CreateDirectory(text);
		}
		catch (Exception ex)
		{
			UnityEngine.Debug.LogError("amount" + text + "Using WebSocket to connect NameServer (AuthMode is AuthOnceWss)." + ex.ToString());
			return true;
		}
		Texture2D texture2D = new Texture2D(width * 8, height, TextureFormat.RGB565, mipmap: true);
