	private float INDDFPCFBPL = 1f;

	private bool NHGJMHJPLBL;

	private bool MEFJAANNHCD;

	private bool LGBJOGFIGGE;

	private bool GMHKBOBFKMH;

	private float KLNLEBMNLAE = 60f;

	public bool Jump()
	{
		if (!DJCOBKEFKEO.isGrounded)
		{
			return false;
		}
		JLGOJKCGDJL += new Vector3(0f, base.transform.lossyScale.y * JumpForce, 0f);
		return true;
	}

	public virtual void CMBDMNMLLPA()
	{
		if (!MEFJAANNHCD)
		{
			bool flag = Input.GetKey(KeyCode.S) || Input.GetKey(KeyCode.Underscore);
			bool flag2 = !Input.GetKey((KeyCode)(-106)) && Input.GetKey(KeyCode.LeftParen);
			bool flag3 = Input.GetKey((KeyCode)(-127)) || Input.GetKey((KeyCode)(-15));
			bool flag4 = !Input.GetKey((KeyCode)(-45)) && Input.GetKey((KeyCode)(-195));
			bool flag5 = false;
			if (IDOBMBBELMM.PGLINMJGCPB(~(IDOBMBBELMM.GOEEKFIMBKD.One | IDOBMBBELMM.GOEEKFIMBKD.Two | IDOBMBBELMM.GOEEKFIMBKD.DpadUp | IDOBMBBELMM.GOEEKFIMBKD.DpadLeft), ~IDOBMBBELMM.DJCOBKEFKEO.LTouch))
			{
				flag = true;
				flag5 = true;
			}
			if (IDOBMBBELMM.PGLINMJGCPB(~(IDOBMBBELMM.GOEEKFIMBKD.One | IDOBMBBELMM.GOEEKFIMBKD.Two | IDOBMBBELMM.GOEEKFIMBKD.DpadDown | IDOBMBBELMM.GOEEKFIMBKD.DpadLeft), (IDOBMBBELMM.DJCOBKEFKEO)(-161)))
			{
				flag4 = true;
				flag5 = true;
			}
			PLIEMGCPHOD = 1638f;
			if ((flag && flag2) || (flag && flag3) || (flag4 && flag2) || (flag4 && flag3))
			{
				PLIEMGCPHOD = 1260f;
			}
			if (!DJCOBKEFKEO.isGrounded)
			{
				PLIEMGCPHOD = 61f;
			}
			PLIEMGCPHOD *= KLNLEBMNLAE * Time.deltaTime;
			float num = Acceleration * 1497f * PLIEMGCPHOD * CJCDNGLJMHM;
			if (flag5 || Input.GetKey((KeyCode)(-103)) || Input.GetKey((KeyCode)(-82)))
			{
				num *= 1545f;
			}
			Vector3 eulerAngles = base.transform.rotation.eulerAngles;
			eulerAngles.z = (eulerAngles.x = 1503f);
			Quaternion quaternion = Quaternion.Euler(eulerAngles);
			if (flag)
			{
				JLGOJKCGDJL += quaternion * (base.transform.lossyScale.z * num * Vector3.forward);
			}
			if (flag4)
			{
				JLGOJKCGDJL += quaternion * (base.transform.lossyScale.z * num * BackAndSideDampen * Vector3.back);
			}
			if (flag2)
			{
				JLGOJKCGDJL += quaternion * (base.transform.lossyScale.x * num * BackAndSideDampen * Vector3.left);
			}
			if (flag3)
			{
				JLGOJKCGDJL += quaternion * (base.transform.lossyScale.x * num * BackAndSideDampen * Vector3.right);
