			Vector3 eulerAngles2 = base.transform.rotation.eulerAngles;
			bool flag6 = IDOBMBBELMM.PGLINMJGCPB(~(IDOBMBBELMM.GOEEKFIMBKD.Two | IDOBMBBELMM.GOEEKFIMBKD.Three | IDOBMBBELMM.GOEEKFIMBKD.DpadDown), (IDOBMBBELMM.DJCOBKEFKEO)(-181));
