		{
			OLFKLJCBHBO -= speedRotationIncrement;
		}
		else if (Input.GetKeyDown((KeyCode)(-65)))
		{
			OLFKLJCBHBO += speedRotationIncrement;
		}
		OHBJMNAFEAN.SetMoveScaleMultiplier(OLFKLJCBHBO);
		float JCPFLMKJAMG = 942f;
