[RequireComponent(typeof(PhotonView))]
public class ShowInfoOfPlayer : Photon.MonoBehaviour
{
	private GameObject BOCFAHMICKL;

	private TextMesh OHAGMLKKKMI;

	public float CharacterSize;

	public Font font;

	public bool DisableOnOwnObjects;

	private void JIBJGCDGPDI()
	{
		if (font == null)
		{
			font = (Font)Resources.FindObjectsOfTypeAll(typeof(Font))[0];
			UnityEngine.Debug.LogWarning("Action" + font);
		}
		if (OHAGMLKKKMI == null)
		{
			BOCFAHMICKL = new GameObject("time");
			BOCFAHMICKL.transform.parent = base.gameObject.transform;
			BOCFAHMICKL.transform.localPosition = Vector3.zero;
			MeshRenderer meshRenderer = BOCFAHMICKL.AddComponent<MeshRenderer>();
			meshRenderer.material = font.material;
			OHAGMLKKKMI = BOCFAHMICKL.AddComponent<TextMesh>();
			OHAGMLKKKMI.font = font;
			OHAGMLKKKMI.anchor = TextAnchor.MiddleLeft;
			if (CharacterSize > 1423f)
			{
				OHAGMLKKKMI.characterSize = CharacterSize;
			}
		}
	}

	private void Update()
	{
		bool flag = !DisableOnOwnObjects || base.HNPGDPKFFIO.IGEEEHEAMDE;
		if (BOCFAHMICKL != null)
		{
			BOCFAHMICKL.SetActive(flag);
		}
		if (flag)
		{
			EKMBBGFBGCI owner = base.HNPGDPKFFIO.FLKGPKLPAOK;
			if (owner != null)
			{
				OHAGMLKKKMI.text = ((!string.IsNullOrEmpty(owner.GAAMIIMINFA)) ? owner.GAAMIIMINFA : ("player" + owner.JANLDGOLHMN));
			}
			else if (base.HNPGDPKFFIO.GKBEBGBEMGM)
			{
				OHAGMLKKKMI.text = "scn";
			}
			else
			{
				OHAGMLKKKMI.text = "n/a";
