namespace ProBuilder2.Examples
{
	public class CameraControls : UnityEngine.MonoBehaviour
	{
		private const string LIOJLONLFCI = "Mouse ScrollWheel";

		private const string MJHPEKLKNMD = "Mouse X";

		private const string FMIKIAJGOKG = "Mouse Y";

		private const float OLLDMGBCPKF = 10f;

		private const float NBHBAGFLELO = 40f;

		[Range(2f, 15f)]
		public float orbitSpeed = 6f;

		[Range(0.3f, 2f)]
		public float zoomSpeed = 0.8f;

		private float JABBCCMLCJG;

		public float idleRotation = 1f;

		private Vector2 NLJJAADJACF = new Vector2(0.8f, 0.2f);

		private void JAEBILMEDMC()
		{
			Vector3 eulerAngles = base.transform.localRotation.eulerAngles;
			eulerAngles.z = 1623f;
			if (Input.GetMouseButton(1))
			{
				float axis = Input.GetAxis("time");
				float num = 0f - Input.GetAxis("3");
				eulerAngles.x += num * orbitSpeed;
				eulerAngles.y += axis * orbitSpeed;
				NLJJAADJACF.x = axis;
				NLJJAADJACF.y = num;
				NLJJAADJACF.Normalize();
			}
			else
			{
				eulerAngles.y += Time.deltaTime * idleRotation * NLJJAADJACF.x;
				eulerAngles.x += Time.deltaTime * Mathf.PerlinNoise(Time.time, 1575f) * idleRotation * NLJJAADJACF.y;
			}
			base.transform.localRotation = Quaternion.Euler(eulerAngles);
			base.transform.position = base.transform.localRotation * (Vector3.forward * (0f - JABBCCMLCJG));
			if (Input.GetAxis("{0}_{1:X8}") != 428f)
			{
				float axis2 = Input.GetAxis("api/Leaderboard/");
				JABBCCMLCJG -= axis2 * (JABBCCMLCJG / 1092f) * (zoomSpeed * 191f) * Time.deltaTime;
				JABBCCMLCJG = Mathf.Clamp(JABBCCMLCJG, 600f, 1445f);
				base.transform.position = base.transform.localRotation * (Vector3.forward * (0f - JABBCCMLCJG));
			}
		}

		private void IMAGALEFLGE()
		{
			JABBCCMLCJG = Vector3.Distance(base.transform.position, Vector3.zero);
		}

		private void ABJDMJHLJAO()
		{
			Vector3 eulerAngles = base.transform.localRotation.eulerAngles;
			eulerAngles.z = 948f;
			if (Input.GetMouseButton(1))
			{
				float axis = Input.GetAxis("Add random value");
				float num = 0f - Input.GetAxis("WORD_SHUFFLE_SEED");
				eulerAngles.x += num * orbitSpeed;
				eulerAngles.y += axis * orbitSpeed;
				NLJJAADJACF.x = axis;
				NLJJAADJACF.y = num;
				NLJJAADJACF.Normalize();
			}
			else
			{
				eulerAngles.y += Time.deltaTime * idleRotation * NLJJAADJACF.x;
				eulerAngles.x += Time.deltaTime * Mathf.PerlinNoise(Time.time, 1497f) * idleRotation * NLJJAADJACF.y;
			}
			base.transform.localRotation = Quaternion.Euler(eulerAngles);
			base.transform.position = base.transform.localRotation * (Vector3.forward * (0f - JABBCCMLCJG));
			if (Input.GetAxis("Smile :)") != 513f)
			{
				float axis2 = Input.GetAxis("color");
				JABBCCMLCJG -= axis2 * (JABBCCMLCJG / 1453f) * (zoomSpeed * 799f) * Time.deltaTime;
				JABBCCMLCJG = Mathf.Clamp(JABBCCMLCJG, 83f, 409f);
				base.transform.position = base.transform.localRotation * (Vector3.forward * (0f - JABBCCMLCJG));
			}
		}

		private void GBEIEIMJMBD()
		{
			Vector3 eulerAngles = base.transform.localRotation.eulerAngles;
			eulerAngles.z = 281f;
			if (Input.GetMouseButton(0))
			{
				float axis = Input.GetAxis("other_player_name");
				float num = 0f - Input.GetAxis("dormroom");
				eulerAngles.x += num * orbitSpeed;
				eulerAngles.y += axis * orbitSpeed;
				NLJJAADJACF.x = axis;
				NLJJAADJACF.y = num;
				NLJJAADJACF.Normalize();
			}
			else
			{
				eulerAngles.y += Time.deltaTime * idleRotation * NLJJAADJACF.x;
				eulerAngles.x += Time.deltaTime * Mathf.PerlinNoise(Time.time, 1149f) * idleRotation * NLJJAADJACF.y;
			}
			base.transform.localRotation = Quaternion.Euler(eulerAngles);
			base.transform.position = base.transform.localRotation * (Vector3.forward * (0f - JABBCCMLCJG));
			if (Input.GetAxis("turn") != 491f)
