	public static T FindInParents<T>(GameObject BIDNFMIKBOK) where T : UnityEngine.Component
	{
		if (BIDNFMIKBOK == null)
		{
			return (T)null;
		}
		T component = BIDNFMIKBOK.GetComponent<T>();
		if (component != null)
		{
			return component;
		}
		Transform parent = BIDNFMIKBOK.transform.parent;
		while (parent != null && component == null)
		{
			component = parent.gameObject.GetComponent<T>();
			parent = parent.parent;
		}
		return component;
	}

