	public bool CHFCPPGMEFL(out FEABNIBDECI LCINHINGAJN, out int IFNPAMHBFFM)
	{
		bool result = false;
		IFNPAMHBFFM = 0;
		LCINHINGAJN = FEABNIBDECI.INVALID;
		if (scoringMode == GLIDEDICKKD.EVERYONE_WINS)
		{
			result = true;
			LCINHINGAJN = gameManager.ECOHKGJCFHB.PFIBLJAGAKH();
		}
		else if (scoringMode == GLIDEDICKKD.WINNER_EXPLICITY_SET)
		{
			FEABNIBDECI[] array = gameManager.ECOHKGJCFHB.NFNLIGPHBEM();
			for (int i = 0; i < array.Length; i++)
			{
				if (KEMPOBBOLKK(array[i]))
				{
					LCINHINGAJN = array[i];
					result = true;
					break;
				}
			}
		}
		else
		{
			result = true;
			FEABNIBDECI[] array2 = gameManager.ECOHKGJCFHB.NFNLIGPHBEM();
			for (int j = 0; j < array2.Length; j++)
			{
				int num = PONIMOCIDFN(array2[j]);
				bool flag = (scoringMode == GLIDEDICKKD.GREATEST_SCORE_WINS && num > IFNPAMHBFFM) || (scoringMode == GLIDEDICKKD.LOWEST_SCORE_WINS && num < IFNPAMHBFFM);
				if (j == 0 || flag)
				{
					IFNPAMHBFFM = num;
					LCINHINGAJN = array2[j];
				}
				else if (num == IFNPAMHBFFM)
				{
					LCINHINGAJN = FEABNIBDECI.INVALID;
				}
			}
		}
		return result;
	}

