		}
		int num = -1;
		List<FEABNIBDECI> list = new List<FEABNIBDECI>();
		for (int i = 1; i < teamConfigs.Length; i++)
		{
			if (PDLPLIKILGA(teamConfigs[i].Team) == 0)
			{
