			}
			int num2 = DMMGKPCIMCE(teamConfigs[i].Team);
			if ((HFOBAHDDKJM == FEABNIBDECI.INVALID || HFOBAHDDKJM != teamConfigs[i].Team) && (num < 0 || num2 <= num))
			{
