				{
					list.Clear();
					num = num2;
				}
				list.Add(teamConfigs[i].Team);
			}
		}
		if (list.Count == 0)
		{
			return FEABNIBDECI.INVALID;
		}
		if (teamSelectionMethod == ABIMJGLBNMO.RANDOM)
		{
			list.Sort(delegate(FEABNIBDECI CCPJAEKECAH, FEABNIBDECI IFKCENFDFJM)
			{
