				return num4.CompareTo((int)IFKCENFDFJM);
			});
			if (HFOBAHDDKJM != FEABNIBDECI.INVALID)
			{
				for (int num3 = 0; num3 < list.Count; num3++)
				{
					if (list[num3] > HFOBAHDDKJM)
					{
						return list[num3];
					}
				}
			}
			return list[1];
		}
		return list[UnityEngine.Random.Range(0, list.Count)];
	}

