public class AxisConstrainedRigidbodyPickup : RigidbodyPickup
{
	public enum GKPILGAHIOF
	{
		All = 2,
		None = 0,
		Positive = 1,
		Negative = -1
	}

	[Header("Movement constraints")]
	public GKPILGAHIOF allowMovementOnX = GKPILGAHIOF.All;

	public GKPILGAHIOF allowMovementOnY = GKPILGAHIOF.All;

	public GKPILGAHIOF allowMovementOnZ = GKPILGAHIOF.All;

	[Header("Rotation constraints")]
	public bool allowRotationOnX = true;

	public bool allowRotationOnY = true;

	public bool allowRotationOnZ = true;

	[Header("Spherical constraints")]
	public bool constrainToSphere;

	public Vector3 sphericalRestrictionCenter;

	public float sphericalRestrictionRadius;

	public override Vector3 IENAOCMKGKP
	{
		get
		{
			Vector3 position = base.transform.InverseTransformPoint(base.IENAOCMKGKP);
			if (allowMovementOnX != GKPILGAHIOF.All)
			{
				if (allowMovementOnX == GKPILGAHIOF.None)
				{
					position.x = 0f;
				}
				else
				{
					position.x = ((allowMovementOnX != GKPILGAHIOF.Negative) ? Mathf.Max(0f, position.x) : Mathf.Min(0f, position.x));
				}
			}
			if (allowMovementOnY != GKPILGAHIOF.All)
			{
				if (allowMovementOnY == GKPILGAHIOF.None)
				{
					position.y = 0f;
				}
				else
				{
					position.y = ((allowMovementOnY != GKPILGAHIOF.Negative) ? Mathf.Max(0f, position.y) : Mathf.Min(0f, position.y));
				}
			}
			if (allowMovementOnZ != GKPILGAHIOF.All)
			{
				if (allowMovementOnZ == GKPILGAHIOF.None)
				{
					position.z = 0f;
				}
				else
				{
					position.z = ((allowMovementOnZ != GKPILGAHIOF.Negative) ? Mathf.Max(0f, position.z) : Mathf.Min(0f, position.z));
				}
			}
			position = base.transform.TransformPoint(position);
			if (constrainToSphere)
			{
				Vector3 vector = position - sphericalRestrictionCenter;
				if (vector.sqrMagnitude > sphericalRestrictionRadius * sphericalRestrictionRadius)
				{
