	private OutfitItem ONNDIGOBIHN(GiftManager.JKEKILJEOGI IGFMOMMLOII, int KCHKNLKDKCA)
	{
		IEnumerable<OutfitItem> enumerable = outfitPrefabs.Where((OutfitItem PBGEEIJJJMB) => PBGEEIJJJMB != null && PBGEEIJJJMB.Level <= KCHKNLKDKCA && PBGEEIJJJMB.Rarity > 0f && PBGEEIJJJMB.DisplayOnRack && (PBGEEIJJJMB.GiftContext & IGFMOMMLOII) == PBGEEIJJJMB.GiftContext);
		float num = 0f;
		foreach (OutfitItem item in enumerable)
		{
			num += item.Rarity;
		}
		float num2 = UnityEngine.Random.Range(0f, num);
		num = 0f;
		foreach (OutfitItem item2 in enumerable)
		{
			if (num2 >= num && num2 <= num + item2.Rarity)
			{
				return item2;
			}
			num += item2.Rarity;
		}
		UnityEngine.Debug.LogError("Failed to find outfit item. This should never happen.");
		return null;
	}

