	public void DebugFillTheDefaultSelection()
	{
		unlockedOutfitSelections.Clear();
		foreach (OutfitItem outfitPrefab in outfitPrefabs)
		{
			unlockedOutfitSelections.Add(new OutfitSelection(outfitPrefab));
			if (outfitPrefab.SelectionGroups == null)
			{
				continue;
			}
			for (int i = 0; i < outfitPrefab.SelectionGroups.Length; i++)
			{
				OutfitItem.OutfitSelectionGroup outfitSelectionGroup = outfitPrefab.SelectionGroups[i];
				if (!outfitSelectionGroup.IsValid)
				{
					continue;
				}
				for (int j = 0; j < outfitSelectionGroup.masks.Count; j++)
				{
					for (int k = 0; k < outfitSelectionGroup.swatches.Count; k++)
					{
						for (int l = 0; l <= outfitSelectionGroup.decals.Count; l++)
						{
							if (l != outfitSelectionGroup.decals.Count || outfitSelectionGroup.decals.Count <= 0 || outfitSelectionGroup.noneDecalRarity != 0f)
							{
								unlockedOutfitSelections.Add(new OutfitSelection(outfitPrefab, (k >= outfitSelectionGroup.swatches.Count) ? null : outfitSelectionGroup.swatches[k], (j >= outfitSelectionGroup.masks.Count) ? null : outfitSelectionGroup.masks[j], (l >= outfitSelectionGroup.decals.Count) ? null : outfitSelectionGroup.decals[l]));
							}
						}
					}
				}
			}
		}
	}

