	public static GameObject CreateFirstPersonShadowCaster(GameObject JFDOMEIADAE)
	{
		GameObject gameObject = null;
		SkinnedMeshRenderer componentInChildren = JFDOMEIADAE.GetComponentInChildren<SkinnedMeshRenderer>();
		if ((bool)componentInChildren && componentInChildren.shadowCastingMode != ShadowCastingMode.Off)
		{
			gameObject = new GameObject();
			gameObject.name = $"{JFDOMEIADAE.name} (FirstPersonShadowCaster)";
			gameObject.transform.SetParent(JFDOMEIADAE.transform);
			gameObject.transform.localPosition = Vector3.zero;
			gameObject.transform.localRotation = Quaternion.identity;
			gameObject.transform.localScale = Vector3.one;
			gameObject.layer = 29;
			gameObject.tag = "LayerIsLocked";
			SkinnedMeshRenderer skinnedMeshRenderer = gameObject.AddComponent<SkinnedMeshRenderer>();
			skinnedMeshRenderer.shadowCastingMode = ShadowCastingMode.ShadowsOnly;
			skinnedMeshRenderer.sharedMesh = componentInChildren.sharedMesh;
			skinnedMeshRenderer.bones = componentInChildren.bones;
			skinnedMeshRenderer.rootBone = componentInChildren.rootBone;
			skinnedMeshRenderer.materials = componentInChildren.materials;
			skinnedMeshRenderer.quality = componentInChildren.quality;
			skinnedMeshRenderer.updateWhenOffscreen = componentInChildren.updateWhenOffscreen;
			skinnedMeshRenderer.skinnedMotionVectors = componentInChildren.skinnedMotionVectors;
			skinnedMeshRenderer.localBounds = componentInChildren.localBounds;
			for (int i = 0; i < componentInChildren.sharedMesh.blendShapeCount; i++)
			{
				skinnedMeshRenderer.SetBlendShapeWeight(i, componentInChildren.GetBlendShapeWeight(i));
			}
		}
		return gameObject;
	}

