[RequireComponent(typeof(Collider))]
public abstract class RecRoomCollider : UnityEngine.MonoBehaviour
{
	private const int NCKMOAFLBMH = 256;

	[SerializeField]
	private float kinematicBounciness = 0.6f;

	[SerializeField]
	private EJNMCBCLLNK impactType;

	[HideInInspector]
	public Rigidbody ThisRigidbody;

	[HideInInspector]
	public TrackedVelocity ThisTrackedVelocity;

	protected float AKJGFPMIKDG;

	private static Collider[] AGNCDFMKGJH = new Collider[256];

	public Collider OOMPPAOOOAH { get; private set; }

	public bool ALMOFJNDEBK { get; private set; }

	public float EHHFNJKECCC => kinematicBounciness;

	public EJNMCBCLLNK BFPBPEGDNOD => impactType;

	private void Awake()
	{
		OOMPPAOOOAH = GetComponent<Collider>();
		ALMOFJNDEBK = OOMPPAOOOAH != null && OOMPPAOOOAH.isTrigger;
	}

	private void OnEnable()
	{
		if (OOMPPAOOOAH != null)
		{
			SphereCollider sphereCollider = OOMPPAOOOAH as SphereCollider;
			if (sphereCollider != null)
			{
				AKJGFPMIKDG = sphereCollider.radius;
			}
			else
			{
				AKJGFPMIKDG = OOMPPAOOOAH.bounds.extents.magnitude;
			}
		}
	}

	public virtual Vector3 GetCollisionNormal(Collision OLAFMLBPNPM)
	{
		Vector3 vector = Vector3.zero;
		if (ThisRigidbody != null)
		{
			if (ThisRigidbody.isKinematic && ThisTrackedVelocity != null)
			{
				vector = ThisTrackedVelocity.HCEEEKBJLGD;
			}
			else if (!ThisRigidbody.isKinematic)
			{
				vector = ThisRigidbody.velocity;
			}
		}
		if (vector.sqrMagnitude < Mathf.Epsilon)
		{
			vector = OLAFMLBPNPM.relativeVelocity.normalized;
		}
		else
		{
			vector.Normalize();
		}
		Vector3 vector2 = Vector3.zero;
		if (OLAFMLBPNPM.contacts != null && OLAFMLBPNPM.contacts.Length > 0)
		{
			ContactPoint contactPoint = OLAFMLBPNPM.contacts[0];
			vector2 = contactPoint.normal;
			Vector3 vector3 = -vector2;
			Vector3 origin = contactPoint.point - vector3;
			if (Physics.Raycast(origin, vector3, out var hitInfo, 2f, 1 << base.gameObject.layer) && Vector3.Dot(hitInfo.normal, vector2) >= 0f)
			{
				vector2 = hitInfo.normal;
			}
		}
		if (vector.sqrMagnitude > Mathf.Epsilon && Vector3.Dot(vector2, vector) < 0.3f)
		{
			vector2 = vector;
		}
		return vector2;
	}

	public bool IsOverlapping(Rigidbody LOGEBJIDOBF)
	{
		int num = Physics.OverlapSphereNonAlloc(OOMPPAOOOAH.bounds.center, AKJGFPMIKDG, AGNCDFMKGJH, 1 << LOGEBJIDOBF.gameObject.layer);
		for (int i = 0; i < num; i++)
		{
			if (AGNCDFMKGJH[i].gameObject == LOGEBJIDOBF.gameObject)
			{
				return true;
			}
		}
		return false;
	}
}
