public static class DOFKBHCPEDH
{
	private static Texture2D DPONGKHMNPK;

	private static Texture2D JOMNGICCOEE;

	private static Material IAILAODDLJC;

	private static Material BHHIJOLAHGL;

	private static Rect EEPNLECHFCI;

	static DOFKBHCPEDH()
	{
		DPONGKHMNPK = null;
		JOMNGICCOEE = null;
		IAILAODDLJC = null;
		BHHIJOLAHGL = null;
		EEPNLECHFCI = new Rect(0f, 0f, 1f, 1f);
