			OODNBHGKNNP.clipping = TextClipping.Clip;
			OODNBHGKNNP.margin.bottom = 0;
		}
		return LFMLLAEIBLH(BDIPBFCGAPI, PCEIJLLIBIN, OMFOMIMHHOP, GJKCHHKDAAL, OODNBHGKNNP);
	}

	public static int LFMLLAEIBLH(int BDIPBFCGAPI, string[] PCEIJLLIBIN, GUIStyle OMFOMIMHHOP, GUIStyle LHDDCLNENHD, GUIStyle OJCKCEPNMAB)
	{
		GUILayout.BeginVertical();
		GUILayout.BeginHorizontal();
		for (int i = 0; i < PCEIJLLIBIN.Length; i++)
		{
			GUIStyle style = ((i != BDIPBFCGAPI) ? OJCKCEPNMAB : LHDDCLNENHD);
			if (GUILayout.Button(PCEIJLLIBIN[i], style))
			{
				BDIPBFCGAPI = i;
			}
		}
		GUILayout.FlexibleSpace();
		GUILayout.EndHorizontal();
		GUILayout.BeginVertical(OMFOMIMHHOP);
		return BDIPBFCGAPI;
	}

	public static void ENAMHFBCEPK()
	{
		GUILayout.EndVertical();
		GUILayout.EndVertical();
	}
