	public T Acquire<T>(T OJLINKDHPIL)
	{
		GLBEIJKKCPE gLBEIJKKCPE = EINCFDGACOJ(OJLINKDHPIL);
		if (gLBEIJKKCPE != null)
		{
			while (gLBEIJKKCPE.EACMBFAKEND.Count > 0)
			{
				GameObject gameObject = gLBEIJKKCPE.EACMBFAKEND[0];
				gLBEIJKKCPE.EACMBFAKEND.RemoveAt(0);
				if (gameObject != null)
				{
					gameObject.SetActive(value: true);
					return gameObject.GetComponent<T>();
				}
				UnityEngine.Debug.LogError("ObjectPool '" + gLBEIJKKCPE.MINLMBIDNAE.name + "' contains a null entry!");
			}
			if (gLBEIJKKCPE.MINLMBIDNAE != null)
			{
				return LCPHKACNDPF(gLBEIJKKCPE.MINLMBIDNAE).GetComponent<T>();
			}
			UnityEngine.Debug.LogError("ObjectPool '" + gLBEIJKKCPE.MINLMBIDNAE.name + "' contains a null Prefab reference!");
		}
		return default(T);
	}

