			return;
		}
		HCCDEAFOLPC = new T[materials.Length];
		T[] componentsInChildren = GetComponentsInChildren<T>(includeInactive: true);
		int i;
		for (i = 0; i < HCCDEAFOLPC.Length && i < componentsInChildren.Length; i++)
		{
			HCCDEAFOLPC[i] = componentsInChildren[i];
