			MILNCPKCGJI.rect = new Rect(0f, 0f, 0.5f, 1f);
			MILNCPKCGJI.Render();
			MILNCPKCGJI.worldToCameraMatrix = KIHIIKBFFGI.GetStereoViewMatrix(Camera.StereoscopicEye.Right);
			MILNCPKCGJI.projectionMatrix = KIHIIKBFFGI.GetStereoProjectionMatrix(Camera.StereoscopicEye.Right);
			MILNCPKCGJI.rect = new Rect(0.5f, 0f, 0.5f, 1f);
			MILNCPKCGJI.Render();
		}
		else
		{
			MILNCPKCGJI.worldToCameraMatrix = KIHIIKBFFGI.worldToCameraMatrix;
			MILNCPKCGJI.projectionMatrix = KIHIIKBFFGI.projectionMatrix;
			MILNCPKCGJI.rect = new Rect(0f, 0f, 1f, 1f);
			MILNCPKCGJI.Render();
		}
		int width = NMFIEGMPEHM.width / 4;
		int height = NMFIEGMPEHM.height / 4;
		RenderTexture renderTexture = RenderTexture.GetTemporary(width, height, 0);
		GJFJALMFHIG.EnableKeyword("COMBINE_MAX");
		GJFJALMFHIG.SetFloat(DDHHLPLBIHK, 0.5f);
		Graphics.Blit(NMFIEGMPEHM, renderTexture, GJFJALMFHIG, 0);
		GJFJALMFHIG.SetFloat(DDHHLPLBIHK, 1f);
		for (int i = 0; i < expandIterations; i++)
		{
			RenderTexture temporary = RenderTexture.GetTemporary(width, height, 0);
			Graphics.Blit(renderTexture, temporary, GJFJALMFHIG, 0);
			RenderTexture.ReleaseTemporary(renderTexture);
			renderTexture = temporary;
		}
		GJFJALMFHIG.DisableKeyword("COMBINE_MAX");
		for (int j = 0; j < blurIterations; j++)
		{
			GJFJALMFHIG.SetFloat(DDHHLPLBIHK, 0.5f + (float)j * 0.6f);
