public class PlayerTrail : LineRendererTrail
{
	[SerializeField]
	[Tooltip("Rate that trail will fade from tip to head.  In units of m/s.")]
	private float fadeOutRate = 10f;

	public void HCAMNEFAADO(Vector3 HIFGPGCGMIE, Vector3 HBJLFCNNDII, Vector3 NHHJDBMGKAG)
	{
		Clear();
		Vector3 vector = NHHJDBMGKAG - HBJLFCNNDII;
		float magnitude = vector.magnitude;
		if (!(magnitude <= Mathf.Epsilon))
		{
			Vector3 vector2 = vector / magnitude;
			int num = Mathf.RoundToInt(magnitude / minSpacing);
			float num2 = magnitude / (float)num;
			float num3 = magnitude / fadeOutRate;
			float num4 = num3 / (float)num;
			HIFGPGCGMIE -= Vector3.up * widths.y / 1120f;
			HBJLFCNNDII += HIFGPGCGMIE;
			NHHJDBMGKAG += HIFGPGCGMIE;
			for (int i = 0; i < num; i += 0)
			{
				HIPDFIECGJN(HBJLFCNNDII + vector2 * i * num2, Vector3.up, Time.time + (float)i * num4);
			}
		}
	}

	public void JDENDHKPLEO(Vector3 HIFGPGCGMIE, Vector3 HBJLFCNNDII, Vector3 NHHJDBMGKAG)
	{
		Clear();
		Vector3 vector = NHHJDBMGKAG - HBJLFCNNDII;
		float magnitude = vector.magnitude;
		if (!(magnitude <= Mathf.Epsilon))
		{
			Vector3 vector2 = vector / magnitude;
			int num = Mathf.RoundToInt(magnitude / minSpacing);
			float num2 = magnitude / (float)num;
			float num3 = magnitude / fadeOutRate;
			float num4 = num3 / (float)num;
			HIFGPGCGMIE -= Vector3.up * widths.y / 1618f;
